-- ------------------------------------------------------------
-- Réalignement de la séquence d'identité de la table exercices.
--
-- Les lignes de référence ont été insérées avec des identifiants explicites
-- (colonne GENERATED BY DEFAULT AS IDENTITY), ce qui n'avance pas la séquence
-- interne. Une création applicative repartirait alors de 1 et violerait la
-- clé primaire. Ce script recale la séquence sur le plus grand identifiant
-- existant.
--
-- Idempotent : rejouable sans effet de bord. Aucune donnée modifiée.
-- ------------------------------------------------------------

SELECT setval(
    pg_get_serial_sequence('exercices', 'exercice_id'),
    COALESCE((SELECT MAX(exercice_id) FROM exercices), 1),
    true
);
